package com.ollie.tierborne.client;
import com.ollie.tierborne.combat.AbilityStatus; import java.util.List;
public final class ClientAbilityState { private static List<AbilityStatus> statuses=List.of();private static float mainCharge=1,offhandCharge=1;private static boolean dualWielding,multislashActive;private static int comboBonus; private ClientAbilityState(){} public static void receive(List<AbilityStatus> value,float main,float offhand,boolean dual,boolean multislash,int combo){statuses=List.copyOf(value);mainCharge=main;offhandCharge=offhand;dualWielding=dual;multislashActive=multislash;comboBonus=combo;} public static List<AbilityStatus> statuses(){return statuses;}public static float mainCharge(){return mainCharge;}public static float offhandCharge(){return offhandCharge;}public static boolean dualWielding(){return dualWielding;}public static boolean multislashActive(){return multislashActive;}public static int comboBonus(){return comboBonus;}public static boolean blocksNormalAttack(){return statuses.stream().anyMatch(s->s.name().equals("Draw Delay")||s.name().equals("Attack Recovery")||s.name().equals("Multislash")&&s.active()||s.name().equals("Fireball")&&s.active()&&!s.stateLabel().equals("RECAST"));} public static void clear(){statuses=List.of();mainCharge=offhandCharge=1;dualWielding=multislashActive=false;comboBonus=0;} }
